package com.sbsolutions.order.models.utils;

import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;

/**
 * Marks a field for inclusion in bullet-point text output generated by
 * {@link AdvancedBulletGenerator}.
 * <p>
 * Apply this annotation to fields of model objects to control how they appear
 * in generated summaries — including display label, sort order, optional emoji
 * prefix, and value formatting rules (multiline, date pattern, or currency).
 * </p>
 *
 * @see AdvancedBulletGenerator
 */
@Retention(RetentionPolicy.RUNTIME)
public @interface BulletField {

  /**
   * The display label shown before the field value (e.g., {@code "Order Date"}).
   *
   * @return the label string
   */
  String label();

  /**
   * Sort order for this field relative to other {@code @BulletField} fields on the
   * same object. Lower values appear first. Defaults to {@code 0}.
   *
   * @return the sort order
   */
  int order() default 0;

  /**
   * Optional emoji prefix inserted between the bullet character and the label
   * (e.g., {@code "📅"}). Empty string means no emoji. Defaults to {@code ""}.
   *
   * @return the emoji string, or empty string for none
   */
  String emoji() default "";

  /**
   * When {@code true}, the label is printed on one line and the value on the
   * next line, useful for long or multi-line values. Defaults to {@code false}.
   *
   * @return {@code true} to format as multiline
   */
  boolean multiline() default false;

  /**
   * A {@link java.time.format.DateTimeFormatter} pattern used to format
   * {@link java.time.temporal.TemporalAccessor} values (e.g., {@code "MM/dd/yyyy"}).
   * Empty string disables date formatting. Defaults to {@code ""}.
   *
   * @return the date format pattern, or empty string for none
   */
  String dateFormat() default "";

  /**
   * When {@code true}, numeric values are formatted as a locale-sensitive
   * currency string using {@link java.text.NumberFormat#getCurrencyInstance()}.
   * Defaults to {@code false}.
   *
   * @return {@code true} to format value as currency
   */
  boolean currency() default false;
}